<?php
if (!defined('ABSPATH')) exit;
function gim_run_job_risk($job_id){ global $wpdb; $job=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('jobs').' WHERE id=%d',$job_id)); if(!$job)return new WP_Error('job','Job not found.'); $find=[];$score=0;$safe=[];
 if($job->urgency==='emergency'){$score+=20;$find[]=['code'=>'EMERGENCY_JOB','points'=>20];$safe[]='REQUIRE_PROVIDER_CONFIRMATION';}
 if(empty(gim_decode($job->evidence_json))){$score+=12;$find[]=['code'=>'LOW_PREWORK_EVIDENCE','points'=>12];$safe[]='REQUIRE_PREWORK_EVIDENCE';}
 $e=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".gim_table('estimates')." WHERE job_id=%d AND status='accepted' ORDER BY id DESC LIMIT 1",$job_id)); if($e&&$e->total_pence>=200000){$score+=18;$find[]=['code'=>'HIGH_VALUE_JOB','points'=>18];$safe[]='REQUIRE_ADMIN_REVIEW';}
 $mat=gim_material_plan($job_id); if($mat&&$mat->ai_decision==='BLOCK'){$score+=45;$find[]=['code'=>'MATERIAL_AI_BLOCK','points'=>45];$safe[]='REQUIRE_MATERIAL_EVIDENCE';} elseif($mat&&$mat->ai_decision==='REVIEW_REQUIRED'){$score+=20;$find[]=['code'=>'MATERIAL_AI_REVIEW','points'=>20];$safe[]='REQUIRE_MATERIAL_EVIDENCE';}
 $sta=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('assurance_runs').' WHERE job_id=%d ORDER BY id DESC LIMIT 1',$job_id)); if($sta&&$sta->decision==='BLOCK'){$score+=45;$find[]=['code'=>'STA_BLOCK','points'=>45];$safe[]='REQUIRE_ADMIN_REVIEW';}
 $score=min(100,$score); $level=$score>=75?'CRITICAL':($score>=50?'HIGH':($score>=20?'MODERATE':'LOW')); if(array_filter($find,fn($f)=>in_array($f['code'],['STA_BLOCK','MATERIAL_AI_BLOCK'],true))&&$level==='MODERATE')$level='HIGH'; $input=hash('sha256',gim_json([$job,$e,$mat,$sta])); $wpdb->insert(gim_table('risk_runs'),['job_id'=>$job_id,'engine_version'=>'gim-dynamic-risk-v1','risk_score'=>$score,'risk_level'=>$level,'findings_json'=>gim_json($find),'safeguards_json'=>gim_json(array_values(array_unique($safe))),'input_digest'=>$input,'created_at'=>gim_now()]); return ['score'=>$score,'level'=>$level,'findings'=>$find,'safeguards'=>array_values(array_unique($safe))]; }
